
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_xpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_xpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.976383823040819e-02, -6.883349961047651e-02, -6.749865984657695e-02, -6.558525671756210e-02, -6.284605610690687e-02, -5.893221854376306e-02, -5.336033577522505e-02, -4.550294869456495e-02, -3.478115877225951e-02, -2.205268686690533e-02, -1.509060444711146e-02, -3.696852431599253e-02, -4.428297811121171e-02, -3.063973275000892e-02, -1.541395135068073e-02, -3.393457785272824e-03, -1.529180524219791e-04, -1.155814514604513e-06, -1.081525706080219e-09, -4.154281064325891e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


